import os
root_dir = '/sasha/3D_LIBRARY/Houdini/Materials' collections = [] titles = []
for item in os.listdir(root_dir): item_path = os.path.join(root_dir, item) if os.path.isdir(item_path): collections.append(item) titles.append(item.replace('_', ' '))
# Sort both lists based on the titles sorted_pairs = sorted(zip(titles, collections)) titles, collections = zip(*sorted_pairs)
choice = hou.ui.selectFromList(titles, exclusive=True, message='Select one of the following options', title='GSG Collections')
if choice: selection = collections[choice[0]] dbfile = os.path.join(root_dir, selection, selection + '.db')
if os.path.exists(dbfile): hou.ui.setSharedAssetGalleryDataSource( hou.AssetGalleryDataSource(dbfile), 'material' )
